import{_ as t,a0 as l,w as o,s as d,ao as c,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"监控 Linux 服务器活动的几个命令 | LCTT x X-CMD","titleTemplate":false,"description":"监控 Linux 服务器活动的几个命令 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"监控 Linux 服务器活动的几个命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"监控 Linux 服务器活动的几个命令 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190123 Commands to help you monitor activity on your Linux server","title":"监控 Linux 服务器活动的几个命令","tag":"201902","desc":""},"relativePath":"201902/20190123 Commands to help you monitor activity on your Linux server.md","filePath":"[post].md"}'),r={name:"201902/20190123 Commands to help you monitor activity on your Linux server.md"};function h(u,s,g,k,b,m){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="监控-linux-服务器活动的几个命令" tabindex="-1">监控 Linux 服务器活动的几个命令 <a class="header-anchor" href="#监控-linux-服务器活动的几个命令" aria-label="Permalink to “监控 Linux 服务器活动的几个命令”">​</a></h1><blockquote><p><code>watch</code>、<code>top</code> 和 <code>ac</code> 命令为我们监视 Linux 服务器上的活动提供了一些十分高效的途径。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/01/owl-face-100785829-large.jpg" alt=""></p><p>为了在获取系统活动时更加轻松，Linux 系统提供了一系列相关的命令。在这篇文章中，我们就一起来看看这些对我们很有帮助的命令吧。</p><h3 id="watch-命令" tabindex="-1">watch 命令 <a class="header-anchor" href="#watch-命令" aria-label="Permalink to “watch 命令”">​</a></h3><p><code>watch</code> 是一个用来轻松地重复检测 Linux 系统中一系列数据命令，例如用户活动、正在运行进程、登录、内存使用等。这个命令实际上是重复地运行一个特定的命令，每次都会重写之前显示的输出，它提供了一个比较方便的方式用以监测在你的系统中发生的活动。</p><p>首先以一个基础且不是特别有用的命令开始，你可以运行 <code>watch -n 5 date</code>，然后你可以看到在终端中显示了当前的日期和时间，这些数据会每五秒更新一次。你可能已经猜到了，<code>-n 5</code> 选项指定了运行接下来一次命令需要等待的秒数。默认是 2 秒。这个命令将会一直运行并按照指定的时间更新显示，直到你使用 <code>^C</code> 停下它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Every 5.0s: date                             butterfly: Wed Jan 23 15:59:14 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Wed Jan 23 15:59:14 EST 2019</span></span></code></pre></div><p>下面是一个更有趣的命令实例，你可以监控一个在服务器中登录用户的列表，该列表会按照指定的时间定时更新。就像下面写到的，这个命令会每 10 秒更新一次这个列表。登出的用户将会从当前显示的列表中消失，那些新登录的将会被添加到这个表格当中。如果没有用户再登录或者登出，这个表格跟之前显示的将不会有任何不同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -n 10 who</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 10.0s: who                             butterfly: Tue Jan 23 16:02:03 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>shs      :0           2019-01-23 09:45 (:0)</span></span>
<span class="line"><span>dory     pts/0        2019-01-23 15:50 (192.168.0.5)</span></span>
<span class="line"><span>nemo     pts/1        2019-01-23 16:01 (192.168.0.15)</span></span>
<span class="line"><span>shark    pts/3        2019-01-23 11:11 (192.168.0.27)</span></span></code></pre></div><p>如果你只是想看有多少用户登录进来，可以通过 <code>watch</code> 调用 <code>uptime</code> 命令获取用户数和负载的平均水平，以及系统的工作状况。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch uptime</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 2.0s: uptime                           butterfly: Tue Jan 23 16:25:48 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 16:25:48 up 22 days,  4:38,  3 users,  load average: 1.15, 0.89, 1.02</span></span></code></pre></div><p>如果你想使用 <code>watch</code> 重复一个包含了管道的命令，就需要将该命令用引号括起来，就比如下面这个每五秒显示一次有多少进程正在运行的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -n 5 &#39;ps -ef | wc -l&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 5.0s: ps -ef | wc -l butterfly: Tue Jan 23 16:11:54 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>245</span></span></code></pre></div><p>要查看内存使用，你也许会想要试一下下面的这个命令组合：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -n 5 free -m</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 5.0s: free -m butterfly: Tue Jan 23 16:34:09 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 5.0s: free -m                          butterfly: Tue Jan 23 16:34:09 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           5959         776        3276          12        1906        4878</span></span>
<span class="line"><span>Swap:          2047           0        2047</span></span></code></pre></div><p>你可以在 <code>watch</code> 后添加一些选项查看某个特定用户下运行的进程，不过 <code>top</code> 为此提供了更好的选择。</p><h3 id="top-命令" tabindex="-1">top 命令 <a class="header-anchor" href="#top-命令" aria-label="Permalink to “top 命令”">​</a></h3><p>如果你想查看某个特定用户下的进程，<code>top</code> 命令的 <code>-u</code> 选项可以很轻松地帮你达到这个目的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ top -u nemo</span></span>
<span class="line"><span>top - 16:14:33 up 2 days,  4:27,  3 users,  load average: 0.00, 0.01, 0.02</span></span>
<span class="line"><span>Tasks: 199 total,   1 running, 198 sleeping,   0 stopped,   0 zombie</span></span>
<span class="line"><span>%Cpu(s):  0.0 us,  0.2 sy,  0.0 ni, 99.8 id,  0.0 wa,  0.0 hi,  0.0 si,  0.0 st</span></span>
<span class="line"><span>MiB Mem :   5959.4 total,   3277.3 free,    776.4 used,   1905.8 buff/cache</span></span>
<span class="line"><span>MiB Swap:   2048.0 total,   2048.0 free,      0.0 used.   4878.4 avail Mem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  PID USER      PR  NI    VIRT    RES    SHR S  %CPU  %MEM     TIME+ COMMAND</span></span>
<span class="line"><span>23026 nemo      20   0   46340   7820   6504 S   0.0   0.1   0:00.05 systemd</span></span>
<span class="line"><span>23033 nemo      20   0  149660   3140     72 S   0.0   0.1   0:00.00 (sd-pam)</span></span>
<span class="line"><span>23125 nemo      20   0   63396   5100   4092 S   0.0   0.1   0:00.00 sshd</span></span>
<span class="line"><span>23128 nemo      20   0   16836   5636   4284 S   0.0   0.1   0:00.03 zsh</span></span></code></pre></div><p>你可能不仅可以看到某个用户下的进程，还可以查看每个进程所占用的资源，以及系统总的工作状况。</p><h3 id="ac-命令" tabindex="-1">ac 命令 <a class="header-anchor" href="#ac-命令" aria-label="Permalink to “ac 命令”">​</a></h3><p>如果你想查看系统中每个用户登录的时长，可以使用 <code>ac</code> 命令。运行该命令之前首先需要安装 <code>acct</code>（Debian 等）或者 <code>psacct</code>（RHEL、Centos 等）包。</p><p><code>ac</code> 命令有一系列的选项，该命令从 <code>wtmp</code> 文件中拉取数据。这个例子展示的是最近用户登录的总小时数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ac</span></span>
<span class="line"><span>        total     1261.72</span></span></code></pre></div><p>这个命令显示了用户登录的总的小时数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ac -p</span></span>
<span class="line"><span>        shark                                5.24</span></span>
<span class="line"><span>        nemo                                 5.52</span></span>
<span class="line"><span>        shs                               1251.00</span></span>
<span class="line"><span>        total     1261.76</span></span></code></pre></div><p>这个命令显示了每天登录的用户小时数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ac -d | tail -10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Jan 11  total        0.05</span></span>
<span class="line"><span>Jan 12  total        1.36</span></span>
<span class="line"><span>Jan 13  total       16.39</span></span>
<span class="line"><span>Jan 15  total       55.33</span></span>
<span class="line"><span>Jan 16  total       38.02</span></span>
<span class="line"><span>Jan 17  total       28.51</span></span>
<span class="line"><span>Jan 19  total       48.66</span></span>
<span class="line"><span>Jan 20  total        1.37</span></span>
<span class="line"><span>Jan 22  total       23.48</span></span>
<span class="line"><span>Today   total        9.83</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Linux 系统上有很多命令可以用于检查系统活动。<code>watch</code> 命令允许你以重复的方式运行任何命令，并观察输出有何变化。<code>top</code> 命令是一个专注于用户进程的最佳选项，以及允许你以动态方式查看进程的变化，还可以使用 <code>ac</code> 命令检查用户连接到系统的时间。</p><hr>`,32)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3335200/linux/how-to-monitor-activity-on-your-linux-server.html"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3335200/linux/how-to-monitor-activity-on-your-linux-server.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/dianbanjiu"},{default:p(()=>[...s[4]||(s[4]=[a("dianbanjiu",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const w=t(r,[["render",h]]);export{x as __pageData,w as default};
